Flg	bra ErrOut	EXPORT EndCallEndCall	ldx #0	EXPORT ErrOutErrOut	pld	; restore direct register	EXPORT oErrOutoErrOut	phy	; save amount to strip on stack	tsc	; get stack pointer	clc	; add to it the amount to strip	adc 1,s	tay	; put this result in Y	tsc	; get back orig stack pointer	phx	; save error on stack	tax	; put orig stack in	X	phb	; now save the data	bank reg	pea $0000	; set data bank reg	to 0	plb	plb	lda |3+4,x	; now use x and y to move 6 bytes	sta |3+4,y	; of rtl info from current pos	lda |3+2,x	; to final pos.	sta |3+2,y	lda |3+0,x	sta |3+0,y	plb	; restore data bank	register	plx	; restore x register with error	tsc	; get stack again	clc	; bump it by amount	to strip Plus 2	adc 1,s	; to make up for amount to strip	adc #2	; still on stack	tcs	; reset stack pointer	txa	; error into a-reg	cmp #1	; set carry correctly	rtl	; fini	EXPORT oBusyECoBusyEC	ldx #0	EXPORT oBusyErroBusyErr	jsl DecBusyFlg	bra oErrOut	EXPORT oEndCalloEndCall	ldx #0	bra oErrOut	ENDPoEndCalls	PROC EXPORT	EXPORT oEndCall0	EXPORT oEndCall2	EXPORT oEndCall4	EXPORT oEndCall6	EXPORT oEndCall8	EXPORT oEndCall10	EXPORT oEndCall12	EXPORT oENDCall14	EXPORT oEndCall16oEndCall0	ldy #0	jml oEndCalloEndCall2	ldy #2	jml oEndCalloEndCall4	ldy #4	jml oEndCalloEndCall6	ldy #6	jml oEndCalloEndCall8	ldy #8	jml oEndCalloEndCall10	ldy #10	jml oEndCalloEndCall12	ldy #12	jml oEndCalloENDCall14	ldy #14	jml oEndCalloEndCall16	ldy #16	jml oEndCall	ENDP	EndCalls	PROC EXPORT	EXPORT EndCall0	EXPORT EndCall2	EXPORT EndCall4	EXPORT EndCall6	EXPORT EndCall8	EXPORT EndCall10	EXPORT EndCall12	EXPORT EndCall14	EXPORT EndCall16EndCall0	ldy #0	jml EndCallEndCall2	ldy #2	jml EndCallEndCall4	ldy #4	jml EndCallEndCall6	ldy #6	jml EndCallEndCall8	ldy #8	jml EndCallEndCall10	ldy #10	jml EndCallEndCall12	ldy #12	jml EndCallEndCall14	ldy #14	jml EndCallEndCall16	ldy #16	jml EndCall	ENDP	oErrOuts	PROC EXPORT	EXPORT oErrOut0	EXPORT oErrOut2	EXPORT oErrOut4	EXPORT oErrOut6	EXPORT oErrOut8	EXPORT oErrOut10	EXPORT oErrOut12	EXPORT oErrOut14	EXPORT oErrOut16oErrOut0	ldy #0	jml oErrOutoErrOut2	ldy #2	jml oErrOutoErrOut4	ldy #4	jml oErrOutoErrOut6	ldy #6	jml oErrOutoErrOut8	ldy #8	jml oErrOutoErrOut10	ldy #10	jml oErrOutoErrOut12	ldy #12	jml oErrOutoErrOut14	ldy #14	jml oErrOutoErrOut16	ldy #16	jml oErrOut	ENDP	ErrOuts	PROC EXPORT	EXPORT ErrOut0	EXPORT ErrOut2	EXPORT ErrOut4	EXPORT ErrOut6	EXPORT ErrOut8	EXPORT ErrOut10	EXPORT ErrOut12	EXPORT ErrOut14	EXPORT ErrOut16ErrOut0	ldy #0	jml ErrOutErrOut2	ldy #2	jml ErrOutErrOut4	ldy #4	jml ErrOutErrOut6	ldy #6	jml ErrOutErrOut8	ldy #8	jml ErrOutErrOut10	ldy #10	jml ErrOutErrOut12	ldy #12	jml ErrOutErrOut14	ldy #14	jml ErrOutErrOut16	ldy #16	jml ErrOut	ENDP	oBusyECs	PROC EXPORT	EXPORT oBusyEC0	EXPORT oBusyEC2	EXPORT oBusyEC4	EXPORT oBusyEC6	EXPORT oBusyEC8	EXPORT oBusyEC10	EXPORT oBusyEC12	EXPORT oBusyEC14	EXPORT oBusyEC16oBusyEC0	ldy #0	jml oBusyECoBusyEC2	ldy #2	jml oBusyECoBusyEC4	ldy #4	jml oBusyECoBusyEC6	ldy #6	jml oBusyECoBusyEC8	ldy #8	jml oBusyECoBusyEC10	ldy #10	jml oBusyECoBusyEC12	ldy #12	jml oBusyECoBusyEC14	ldy #14	jml oBusyECoBusyEC16	ldy #16	jml oBusyEC	ENDP	BusyECs	PROC EXPORT	EXPORT BusyEC0	EXPORT BusyEC2	EXPORT BusyEC4	EXPORT BusyEC6	EXPORT BusyEC8	EXPORT BusyEC10	EXPORT BusyEC12	EXPORT BusyEC14	EXPORT BusyEC16BusyEC0	ldy #0	jml BusyECBusyEC2	ldy #2	jml BusyECBusyEC4	ldy #4	jml BusyECBusyEC6	ldy #6	jml BusyECBusyEC8	ldy #8	jml BusyECBusyEC10	ldy #10	jml BusyECBusyEC12	ldy #12	jml BusyECBusyEC14	ldy #14	jml BusyECBusyEC16	ldy #16	jml BusyEC	ENDP	oBusyErrs	PROC EXPORT	EXPORT oBusyErr0	EXPORT oBusyErr2	EXPORT oBusyErr4	EXPORT oBusyErr6	EXPORT oBusyErr8	EXPORT oBusyErr10	EXPORT oBusyErr12	EXPORT oBusyErr14	EXPORT oBusyErr16oBusyErr0	ldy #0	jml oBusyErroBusyErr2	ldy #2	jml oBusyErroBusyErr4	ldy #4	jml oBusyErroBusyErr6	ldy #6	jml oBusyErroBusyErr8	ldy #8	jml oBusyErroBusyErr10	ldy #10	jml oBusyErroBusyErr12	ldy #12	jml oBusyErroBusyErr14	ldy #14	jml oBusyErroBusyErr16	ldy #16	jml oBusyErr	ENDP	BusyErrs	PROC EXPORT	EXPORT BusyErr0	EXPORT BusyErr2	EXPORT BusyErr4	EXPORT BusyErr6	EXPORT BusyErr8	EXPORT BusyErr10	EXPORT BusyErr12	EXPORT BusyErr14	EXPORT BusyErr16BusyErr0	ldy #0	jml BusyErrBusyErr2	ldy #2	jml BusyErrBusyErr4	ldy #4	jml BusyErrBusyErr6	ldy #6	jml BusyErrBusyErr8	ldy #8	jml BusyErrBusyErr10	ldy #10	jml BusyErrBusyErr12	ldy #12	jml BusyErrBusyErr14	ldy #14	jml BusyErrBusyErr16	ldy #16	jml BusyErr	ENDP	NotImp	PROC EXPORT	lda #$04FF	sec	rtl	ENDP		END